-- Manufacturer-backed catalog snapshot. Sources and coverage: docs/catalog-sources.md.
-- Upserts preserve UUIDs, inactive state, existing aliases and manually entered specifications.
insert into public.catalog_product_models as current(category,brand,name,variant,aliases,specs,source_url)
select category,brand,name,variant,aliases,specs,source_url from jsonb_to_recordset($catalog$
